#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define RULE110 0x5418C0

int main(int argc, char **argv) {
    if (argc < 3) {
        printf("INVALID_INPUT\n");
        return 1;
    }

    int rows = strtol(argv[1], NULL, 10);
    if (rows < 0) {
        printf("INVALID_INPUT\n");
        return 1;
    }

    char *init_row = argv[2];
    int init_row_len = strlen(init_row);
    if (init_row_len < 3) {
        printf("INVALID_INPUT\n");
        return 1;
    }

    char row[200];
    strcpy(row, init_row);

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < init_row_len; j++) {
            int left = (j - 1 + init_row_len) % init_row_len;
            int center = j;
            int right = (j + 1) % init_row_len;
            int config = (row[left] - '0') * 4 + (row[center] - '0') * 2 + (row[right] - '0');
            row[j] = (RULE110 >> (7 - config)) & 1 ? '1' : '0';
        }
        printf("%s\n", row);
    }

    return 0;
}
